namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();
        foreach (var item in items)
        {
            if (TryBuildPlanEntry(item, supplier, season, out var entry))
                plan.Add(entry);
        }

        return plan;
    }

    private static bool TryBuildPlanEntry(
        StockItem item,
        ISupplier supplier,
        int season,
        out string entry)
    {
        entry = string.Empty;
        if (!TryCalculateOrderQuantity(item, season, out int orderQuantity))
            return false;
        if (string.IsNullOrEmpty(item.Sku))
            return false;

        bool placed = supplier.PlaceOrder(item.Sku, orderQuantity);
        entry = FormatPlanEntry(item.Sku, orderQuantity, placed);
        return true;
    }

    private static bool TryCalculateOrderQuantity(
        StockItem item,
        int season,
        out int orderQuantity)
    {
        orderQuantity = 0;
        if (item.OnHand < 0)
            return false;

        int available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint)
            return false;

        int deficit = item.ReorderPoint - available;
        orderQuantity = CalculateBaseOrderQuantity(deficit);
        orderQuantity = ApplySeasonalAdjustment(orderQuantity, season);
        return orderQuantity > 0;
    }

    private static int CalculateBaseOrderQuantity(int deficit)
    {
        if (deficit <= 0)
            return 0;
        if (deficit < 10)
            return 10;
        if (deficit < 100)
            return deficit;

        return deficit + 50;
    }

    private static int ApplySeasonalAdjustment(int orderQuantity, int season)
    {
        if (season == 4 && orderQuantity > 0)
            return (int)(orderQuantity * 1.5);
        if (season == 1)
            return orderQuantity / 2;

        return orderQuantity;
    }

    private static string FormatPlanEntry(string sku, int orderQuantity, bool placed)
    {
        if (placed && orderQuantity > 200)
            return $"{sku}:LARGE:{orderQuantity}";
        if (placed)
            return $"{sku}:{orderQuantity}";

        return $"{sku}:FAILED";
    }
}
